CREATE DATABASE IF NOT EXISTS urlshortener CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE urlshortener;
CREATE TABLE IF NOT EXISTS users (id BIGINT PRIMARY KEY AUTO_INCREMENT,email VARCHAR(190) NOT NULL,password_hash VARCHAR(100) NOT NULL,role VARCHAR(40) NOT NULL DEFAULT 'USER',created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),CONSTRAINT uk_users_email UNIQUE(email));
CREATE TABLE IF NOT EXISTS shortened_urls (id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,short_code VARCHAR(32) NOT NULL,original_url VARCHAR(2048) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,expires_at TIMESTAMP(6) NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),CONSTRAINT uk_short_code UNIQUE(short_code),CONSTRAINT fk_short_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX idx_short_urls_owner_created(user_id,created_at),INDEX idx_short_urls_expires(expires_at));
CREATE TABLE IF NOT EXISTS click_events (id BIGINT PRIMARY KEY AUTO_INCREMENT,shortened_url_id BIGINT NOT NULL,clicked_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),referrer VARCHAR(1024) NULL,device_category VARCHAR(30) NULL,browser VARCHAR(80) NULL,CONSTRAINT fk_click_url FOREIGN KEY(shortened_url_id) REFERENCES shortened_urls(id) ON DELETE CASCADE,INDEX idx_click_url_time(shortened_url_id,clicked_at),INDEX idx_click_time(clicked_at));
